INSERT INTO notification_templates (id, code, subject_template, body_template, description, active, created_at, updated_at, created_by, updated_by) VALUES
  (UUID(), 'PASSWORD_RESET', 'Reset your HR Portal password', 'Hello {{name}}, use this token to reset your password (valid {{expiresMinutes}} minutes): {{token}}. If you did not ask for this, ignore this message.', 'Seeded template', 1, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), 'flyway', 'flyway'),
  (UUID(), 'ACCOUNT_PROVISIONED', 'Your HR Portal account is ready', 'Welcome {{name}}! Your user name is {{username}}. Use ''Forgot password'' on the login page to set your password.', 'Seeded template', 1, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), 'flyway', 'flyway'),
  (UUID(), 'LEAVE_APPLIED', 'Leave request from {{employeeName}}', '{{employeeName}} applied for {{leaveType}} from {{fromDate}} to {{toDate}} ({{days}} day(s)). Please review it.', 'Seeded template', 1, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), 'flyway', 'flyway'),
  (UUID(), 'LEAVE_APPROVED', 'Your leave was approved', 'Your {{leaveType}} from {{fromDate}} to {{toDate}} ({{days}} day(s)) was approved. {{comment}}', 'Seeded template', 1, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), 'flyway', 'flyway'),
  (UUID(), 'LEAVE_REJECTED', 'Your leave was rejected', 'Your {{leaveType}} from {{fromDate}} to {{toDate}} was rejected. Reason: {{comment}}', 'Seeded template', 1, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), 'flyway', 'flyway'),
  (UUID(), 'LEAVE_CANCELLED', 'Leave cancelled', 'The {{leaveType}} from {{fromDate}} to {{toDate}} was cancelled. {{comment}}', 'Seeded template', 1, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), 'flyway', 'flyway'),
